  { const R = clean(F.three); banded(R, yP, yG + 144, 3.9); edgeP(B.p('#e0dbd2'), R, yG + 143.4, 0.6, 0.9, 0.1); prismP(B.p(ESR2), clean(offP(R, 4)), yG + 144, yG + 148); }
